"""⚠️ SECURITY: `run_command` executes shell commands generated by the language
model on the machine running this app. Commands that do more than read require
human approval in Slack before they run (see `agent/approvals.py`) — only ever
run this against trusted, throwaway repositories in the session temp directory.
See the README security section.
"""

import subprocess
from logging import getLogger
from pathlib import Path

from agents import function_tool
from agents.run_context import RunContextWrapper

from agent.approvals import command_needs_approval
from agent.deps import AgentDeps
from agent.guardrails import session_stopped

logger = getLogger(__name__)

# Cap any single command so a hung/looping command can't wedge the session.
COMMAND_TIMEOUT_SECONDS = 120


async def needs_approval(_ctx, arguments: dict, _call_id: str) -> bool:
    """The SDK's `needs_approval` hook, checked with the tool's arguments before it runs.

    Returning True pauses the run with a ToolApprovalItem the listener handles.
    """
    command = (arguments or {}).get("command", "")
    needs = command_needs_approval(command)
    if needs:
        logger.info("run_command needs approval: %s", command)
    return needs


@function_tool(
    needs_approval=needs_approval,
    tool_input_guardrails=[session_stopped],
)
def run_command(wrapper: RunContextWrapper[AgentDeps], command: str) -> str:
    """Run a shell command in the session's working directory and return its output.

    Use it to inspect, build, test, and edit the cloned repository (grep, cat,
    sed, pytest, git, and so on). Clone a repo with `clone_repo` first. Read-only
    commands run immediately; anything else, including tests and builds, asks the
    user to approve it in Slack before running.

    Args:
        command: The shell command to run, executed with the cloned repo as cwd.
    """
    session = wrapper.context.session
    if not session.workdir or not Path(session.workdir).is_dir():
        return "No working directory yet — call clone_repo first."

    try:
        result = subprocess.run(
            command,
            shell=True,
            cwd=session.workdir,
            capture_output=True,
            text=True,
            timeout=COMMAND_TIMEOUT_SECONDS,
            check=False,
        )
    except subprocess.TimeoutExpired:
        return f"Command timed out after {COMMAND_TIMEOUT_SECONDS}s: {command}"

    out = (result.stdout or "").strip()
    err = (result.stderr or "").strip()
    parts = [f"exit={result.returncode}"]
    if out:
        parts.append(f"stdout:\n{out[:4000]}")
    if err:
        parts.append(f"stderr:\n{err[:2000]}")
    return "\n".join(parts)
